import{_ as a,o as s,c as i,a3 as r}from"./chunks/framework.B7pF4b99.js";const b=JSON.parse('{"title":"Spec 32：PLIC 外部中斷派發骨架","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-32-plic-external-interrupts.md","filePath":"SPEC-32-plic-external-interrupts.md","lastUpdated":1794274556000}'),l={name:"SPEC-32-plic-external-interrupts.md"};function n(t,e,c,p,o,d){return s(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="spec-32-plic-外部中斷派發骨架" tabindex="-1">Spec 32：PLIC 外部中斷派發骨架 <a class="header-anchor" href="#spec-32-plic-外部中斷派發骨架" aria-label="Permalink to &quot;Spec 32：PLIC 外部中斷派發骨架&quot;">​</a></h1><blockquote><p>2026-11-10 合併註記：本文記錄本機分支的同步原型。現行程式已移植到遠端模組架構，磁碟使用 KernelGate、event、bounce buffer 與有界 reset/offline；IRQ 與 polling 共用 <code>poll_device</code>。FS／VM 使用遠端 KernelGate；本機 mutex 留在 <code>kernel/proc/kmutex.*</code> 與主機測試作為獨立原型，未接入 runtime。現況與驗證見<a href="./merge-2026-11-10.html">合併紀錄</a>。</p></blockquote><p>狀態：演算法已獲同意，第一階段程式碼已實作；編譯與 QEMU 驗證待使用者執行。</p><h2 id="本階段範圍" tabindex="-1">本階段範圍 <a class="header-anchor" href="#本階段範圍" aria-label="Permalink to &quot;本階段範圍&quot;">​</a></h2><p>建立裝置 IRQ 到 supervisor trap 的通知通道，先以已初始化的 WUFS／swap VirtIO block 裝置接入。磁碟請求仍同步輪詢完成；不在本階段加入睡眠／喚醒、核心內搶占、鍵盤／GPU IRQ 或 SMP。</p><p>實作順序為 FDT 探索、supervisor-only MMIO 映射、註冊驅動 callback、設定 PLIC、開啟 <code>sie.SEIE</code>。保留 kernel 的全域中斷關閉規則，外部事件可在返回 U-mode 後處理。</p><h2 id="fdt-與映射" tabindex="-1">FDT 與映射 <a class="header-anchor" href="#fdt-與映射" aria-label="Permalink to &quot;FDT 與映射&quot;">​</a></h2><ul><li>新增有界、免配置的 FDT 讀取器：DTB 最多 1 MiB、128 nodes、32 層，檢查 token、區塊範圍、名稱結尾及 properties-before-children 順序。</li><li>從 <code>riscv,plic0</code>／<code>sifive,plic-1.0.0</code> 的 <code>reg</code>、<code>riscv,ndev</code>、<code>interrupts-extended</code> 找到啟動 hart 的 supervisor external context，沒有寫死 context 編號。</li><li>VirtIO 路由依 MMIO <code>reg</code>、有效 <code>interrupt-parent</code> phandle 與 <code>interrupts</code> 建立，不依磁碟掛載順序或固定 IRQ ID。</li><li>只映射 priority、所選 enable bank 與 threshold／claim context 所需的三個頁面，PTE 不含使用者存取權。</li><li>僅支援 QEMU virt 的 identity bus、CPU interrupt controller 單 cell 與 VirtIO MMIO 單 source 綁定。格式不符、來源重複或缺少可用 PLIC 時保留原輪詢模式。</li></ul><h2 id="派發與確認" tabindex="-1">派發與確認 <a class="header-anchor" href="#派發與確認" aria-label="Permalink to &quot;派發與確認&quot;">​</a></h2><p><code>trap_handler</code> 識別最高位為中斷且原因碼為 9 的 supervisor external interrupt：</p><ol><li>從目前 context 的 claim register 讀取 IRQ ID；零表示沒有待處理來源。</li><li>有 callback 時，呼叫驅動確認裝置事件，再將同一 ID 寫回 PLIC complete。</li><li>沒有 callback 時，先 complete，再關閉該來源的 enable bit。PLIC 對已停用來源的 completion 會忽略，因此不能先 mask 再 complete。</li><li>不合法 ID 不可用於陣列或暫存器索引；記錄錯誤並關閉 SEIE，保留輪詢備援。</li><li>每次最多領取 32 個來源。達到上限時關閉 SEIE 並記錄 budget 計數，避免立即重入形成中斷風暴；目前只有同步磁碟來源，正常處理不應耗盡此上限。</li><li>外部中斷不增加 <code>sepc</code>。U-mode 返回使用既有 <code>process_resume</code>；kernel trap 直接返回原 frame，不假設排程器目前有行程。</li></ol><p>VirtIO block callback 讀取 <code>InterruptStatus</code>、保留已觀察的通知位元、寫入 <code>InterruptACK</code>，並使用 I/O fence 保證裝置 ACK 先於 PLIC complete。後續 <a href="./SPEC-33-block-request-ownership.html">Spec 33</a> 已將完成檢查集中到共用 collector，輪詢與 callback 都能呼叫；callback 不輪詢、不輸出、不切換行程或釋放請求記憶體，<code>transfer</code> 仍持有緩衝區直到完成。執行期間調整磁碟容量不在支援範圍。</p><h2 id="可觀察的驗證方式" tabindex="-1">可觀察的驗證方式 <a class="header-anchor" href="#可觀察的驗證方式" aria-label="Permalink to &quot;可觀察的驗證方式&quot;">​</a></h2><p>在專案根目錄執行下列其中一種方式，自動編譯後啟動：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 日常 CLI；會依原有流程準備正常磁碟</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Start-WUWAOS.cmd</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 使用獨立測試磁碟，離開後也會檢查磁碟內容</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> valid</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>開機應出現 <code>[irq] PLIC context=... sources=... registered=...</code>。預設 WUFS／swap 皆可用時，應註冊兩個來源。若看到 <code>retaining polling</code>，代表相容性備援啟動，不能當成本階段 IRQ 驗證通過。</p><p>在客體 shell 執行：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ps</span></span>
<span class="line"><span>ls /</span></span>
<span class="line"><span>ps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>ps</code> 會多列出：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IRQ: PLIC=enabled external=... claims=... unhandled=0 invalid=0 budget=0</span></span>
<span class="line"><span>  IRQ ... WUFS handled=... spurious=...</span></span>
<span class="line"><span>  IRQ ... swap handled=... spurious=...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>應確認 <code>PLIC=enabled</code>，<code>ls /</code> 正常返回，第二次 <code>ps</code> 的 WUFS <code>handled</code> 比第一次增加；<code>unhandled</code>、<code>invalid</code>、<code>budget</code> 保持零。計數是通知／claim 次數，不等於磁區請求數；多筆同步 I/O 在返回 U-mode 前可能合併成一次通知。開機已完成的 I/O 也可能讓第一次計數大於零。</p><p>再反轉磁碟掛載順序，使用同樣操作確認角色與 IRQ 路由仍正確：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\Test-FsDisk.cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> valid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">reverse</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">disks</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>按 Ctrl+A，放開後按 X 離開 QEMU。測試工具的 <code>PASS</code> 只確認磁碟內容，IRQ 計數仍須人工確認。GUI 可用 <code>.\\Start-WUWAOS.cmd gui</code> 回歸滑鼠、鍵盤和 Terminal；這些裝置仍走原有輪詢。原有 <code>blank</code>／<code>damaged</code>／<code>tail</code> 案例可繼續回歸磁碟保護。</p><h2 id="尚待驗證與下一階段" tabindex="-1">尚待驗證與下一階段 <a class="header-anchor" href="#尚待驗證與下一階段" aria-label="Permalink to &quot;尚待驗證與下一階段&quot;">​</a></h2><p>尚未執行本版核心編譯、一般／反轉磁碟 QEMU 操作、GUI 回歸或中斷風暴／未知來源故障注入。文件建置不代替這些驗證。</p><p>使用者已要求保留測試提醒並繼續實作；本項尚未驗證。<a href="./SPEC-33-block-request-ownership.html">Spec 33</a> 先整理每裝置請求所有權與完成檢查。真正的原子檢查／等待／喚醒，仍需處理上層緩衝區、swap 路徑、kernel 鎖與排程器安全中斷時機；不能宣稱已消除忙等。</p><h2 id="程式碼與規格" tabindex="-1">程式碼與規格 <a class="header-anchor" href="#程式碼與規格" aria-label="Permalink to &quot;程式碼與規格&quot;">​</a></h2><ul><li><a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/fdt.c" target="_blank" rel="noreferrer">arch/riscv/fdt.c</a>、<a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/irq.c" target="_blank" rel="noreferrer">arch/riscv/irq.c</a>：FDT 及 PLIC 派發。</li><li><a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/trap.c" target="_blank" rel="noreferrer">arch/riscv/trap.c</a>、<a href="https://github.com/johnson931128/WUWAOS/blob/main/drivers/virtio/block.c" target="_blank" rel="noreferrer">drivers/virtio/block.c</a>：外部陷阱及裝置 ACK。</li><li><a href="https://docs.riscv.org/reference/plic/v1.0.0/plic-claims.html" target="_blank" rel="noreferrer">RISC-V PLIC claim</a>、<a href="https://docs.riscv.org/reference/plic/v1.0.0/plic-completion.html" target="_blank" rel="noreferrer">PLIC completion</a>。</li><li><a href="https://www.qemu.org/docs/master/system/riscv/virt.html" target="_blank" rel="noreferrer">QEMU virt 平台</a>、<a href="https://docs.oasis-open.org/virtio/virtio/v1.3/virtio-v1.3.html" target="_blank" rel="noreferrer">VirtIO 1.3</a>。</li></ul>`,29)])])}const u=a(l,[["render",n]]);export{b as __pageData,u as default};
